Here is the current implementation of a Python module.
```python
class Gradebook:
    def __init__(self) -> None:
        # assignment name -> (weight, kind)
        self._assignments = {}
        # student -> {assignment name: grade}
        self._records = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        if kind not in ("homework", "quiz"):
            raise ValueError(f"Invalid assignment kind: {kind!r}")
        self._assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the 2.0-5.0 scale")
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment!r}")
        self._records.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self._records.get(student, {})

        # Determine the lowest quiz grade to drop (only if more than one quiz)
        quizzes = [
            (name, student_grades.get(name, 2.0))
            for name, (_, kind) in self._assignments.items()
            if kind == "quiz"
        ]
        dropped_quiz = None
        if len(quizzes) > 1:
            dropped_quiz = min(quizzes, key=lambda ng: ng[1])[0]

        total_weight = 0.0
        weighted_sum = 0.0
        for name, (weight, _kind) in self._assignments.items():
            if name == dropped_quiz:
                continue
            grade = student_grades.get(name, 2.0)
            weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0:
            return 0.0
        return round(weighted_sum / total_weight, 2)

    def students(self) -> list[str]:
        return sorted(student for student, grades in self._records.items() if grades)

    def grades(self, student: str) -> dict[str, float]:
        return dict(self._records.get(student, {}))
```

